def assign_to_opportunity_owners(apps, schema_editor):
    """Existing contacts go to the owner of their latest opportunity, so sellers keep seeing
    the contacts they already work. Contacts without opportunities stay unassigned."""
    Contact = apps.get_model("contacte", "Contact")
    Opportunity = apps.get_model("oportunitati", "Opportunity")
    for contact in Contact.objects.filter(opportunities__isnull=False).distinct():
        latest = Opportunity.objects.filter(contact=contact).order_by("-updated_at").first()
        contact.assigned_to_id = latest.owner_id
        contact.save(update_fields=["assigned_to"])


